image_source:
[Module load: #json];
[System load: "modules/json.birnam"];
let token := "\"plain\"";
[Reflect defineMethod: #replacementCopy:to: on: token as: [:self :from :to | "changed"]];
let main := [|
  [System println: [Json stringify: [Json parse: "[null,true,{\"n\":2},\"x\"]"]]];
  let first := [token jsonDecodeString];
  [System println: first];
  [System println: [first == token]];
  [System println: [first == [token jsonDecodeString]]];
  [System println: ["\"a\\tb\"" jsonDecodeString]];
  [[Reflect vtableOf: token] addMethod: [token methodFor: #replacementCopy:to:] as: #copyFrom:to:];
  [System gc];
  [System println: [token jsonDecodeString]]
];
[System saveImage: "/tmp/birnam-json-next/main.image"];
[System println: [[System imageSaveReport] status]]
